struct ByLength {
    bool operator()(const std::string& a,
                    const std::string& b) const {
        return a.size() < b.size();
    }
};

std::set<std::string, ByLength> s = {"kiwi", "fig", "pear"};
for (auto& w : s) std::cout << w << ' ';   // fig kiwi

